def is_power_of_five(x):
    if x <= 0:
        return False
    while x > 1 and x % 5 == 0:
        x //= 5
    return x == 1

solutions = []
print("n | 2^n - 3 | Is power of 5?")
for n in range(3, 13):
    value = (2**n) - 3
    is_p5 = is_power_of_five(value)
    print(f"{n:2} | {value:7} | {is_p5}")
    if is_p5:
        solutions.append(n)

print("\nSolutions found:", solutions)

